import sys
from cli_common import dispatch, help_dispatch

COMMANDS = set('doctor help license add apply chattr diff edit forget init merge merge-all re-add status update cat data execute-template cd edit-config edit-config-template generate git ignored managed unmanaged verify age age-keygen decrypt edit-encrypted encrypt docker ssh archive destroy import purge upgrade cat-config completion dump dump-config secret source-path state target-path'.split())


def main(argv):
    result = dispatch(argv)
    if result[0] is not None:
        return result
    result = help_dispatch(argv)
    if result is not None:
        return result
    if not argv:
        return dispatch([])
    # Cobra accepts global flags before the command. Locate the first non-flag
    # token while accounting for global options that consume a value.
    value_flags = {'--age-recipient', '--age-recipient-file', '--cache', '--color', '--config', '-c', '--config-format', '--destination', '-D', '--mode', '-o', '--output', '--override-data', '--override-data-file', '--persistent-state', '--progress', '--refresh-externals', '--source', '-S', '--working-tree', '-W'}
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in value_flags:
            i += 2
            continue
        if arg.startswith('-'):
            if arg in ('-h', '--help'):
                return dispatch(['--help'])
            if arg.startswith('--'):
                return (1, '', 'chezmoi: unknown flag: %s\n' % arg)
            return (1, '', "chezmoi: unknown shorthand flag: '%s' in %s\n" % (arg[1:2], arg))
        command = arg
        break
    else:
        return dispatch([])
    if command not in COMMANDS:
        return (1, '', 'chezmoi: unknown command "%s" for "chezmoi"\n' % command)
    # The selected command handler modules are added independently as they land.
    return (1, '', 'chezmoi: %s is not implemented\n' % command)


if __name__ == '__main__':
    code, out, err = main(sys.argv[1:])
    sys.stdout.write(out)
    sys.stderr.write(err)
    raise SystemExit(code)

