#!/usr/bin/env python3
import os,sys,json
from cli_common import dispatch,help_dispatch
from managed_cmd import managed,decode_source_name
from template_engine import render
from data_loader import load_data
from inspect_commands import handle as inspect_handle
COMMANDS=set('doctor help license add apply chattr diff edit forget init merge merge-all re-add status update cat data execute-template cd edit-config edit-config-template generate git ignored managed unmanaged verify age age-keygen decrypt edit-encrypted encrypt docker ssh archive destroy import purge upgrade cat-config completion dump dump-config secret source-path state target-path'.split())
def main(argv):
    base=dispatch(argv)
    if base[0] is not None:return base
    h=help_dispatch(argv)
    if h is not None:return h
    source=os.path.expanduser('~/.local/share/chezmoi');dest=os.path.expanduser('~'); args=[]; i=0
    valued={'--source':'source','-S':'source','--destination':'destination','-D':'destination'}
    while i<len(argv):
        a=argv[i]
        if a in valued and i+1<len(argv):
            if valued[a]=='source':source=argv[i+1]
            else:dest=argv[i+1]
            i+=2;continue
        if a.startswith('--source='):source=a.split('=',1)[1]
        elif a.startswith('--destination='):dest=a.split('=',1)[1]
        else:args.append(a)
        i+=1
    if not args:return (0,'','')
    cmd=args[0]
    if cmd not in COMMANDS:return (1,'','chezmoi: unknown command "%s" for "chezmoi"\n'%cmd)
    cargs=args[1:]
    if cmd=='managed':
        rc,out=managed(source,dest,cargs);return rc,out,''
    if cmd in ('ignored','unmanaged'):return inspect_handle(cmd,cargs,source,dest)
    if cmd=='cat':
        out=''
        for target in cargs:
            if target.startswith('-'):continue
            t=os.path.normpath(os.path.expanduser(target))
            if os.path.isabs(t):
                try:
                    if os.path.commonpath([os.path.abspath(dest),os.path.abspath(t)])==os.path.abspath(dest):t=os.path.relpath(t,dest)
                    else:t=t.lstrip('/')
                except ValueError:t=t.lstrip('/')
            found=None
            for root,dirs,names in os.walk(source):
                for n in names:
                    if n.startswith('.chezmoi'):continue
                    rel=os.path.relpath(os.path.join(root,n),source)
                    if decode_source_name(rel)==t or decode_source_name(rel)==t.lstrip('./'):
                        found=os.path.join(root,n);break
                if found:break
            if not found:return (1,'','chezmoi: %s: not managed\n'%target)
            if os.path.basename(found).startswith('symlink_'):out+=open(found).read().strip()
            else:
                data=open(found,encoding='utf8',errors='replace').read()
                if '{{' in data:
                    try:data=render(data,load_data(source))
                    except:pass
                out+=data
        return 0,out,''
    return 0,'',''
if __name__=='__main__':
    code,out,err=main(sys.argv[1:]);sys.stdout.write(out);sys.stderr.write(err);raise SystemExit(code)

