COMMANDS=set('doctor help license add apply chattr diff edit forget init merge merge-all re-add status update cat data execute-template cd edit-config edit-config-template generate git ignored managed unmanaged verify age age-keygen decrypt edit-encrypted encrypt docker ssh archive destroy import purge upgrade cat-config completion dump dump-config secret source-path state target-path'.split())

def yaml_dump(value, indent=0):
    pad=' '*indent
    if isinstance(value,dict):
        lines=[]
        for key in sorted(value):
            val=value[key]
            k=str(key) if str(key).replace('_','').isalnum() else json.dumps(str(key),ensure_ascii=False)
            if isinstance(val,(dict,list)) and val:
                lines.append(pad+k+':')
                lines.append(yaml_dump(val,indent+2).rstrip('\n'))
            else:
                lines.append(pad+k+': '+yaml_scalar(val))
        return '\n'.join(lines)+'\n'
    if isinstance(value,list):
        return ''.join(pad+'- '+yaml_scalar(x)+'\n' for x in value)
    return pad+yaml_scalar(value)+'\n'

def yaml_scalar(value):
    if value is None:return 'null'
    if isinstance(value,bool):return 'true' if value else 'false'
    if isinstance(value,(dict,list)):return json.dumps(value,ensure_ascii=False,separators=(',',':'))
    if isinstance(value,(int,float)):return str(value)
    s=str(value)
    if not s or s.strip()!=s or any(ch in s for ch in ':#{}[],&*?!|>\'"%@`') or s.lower() in ('null','true','false','yes','no'):
        return json.dumps(s,ensure_ascii=False)
    return s

def chezmoi_context(source,dest,command):
    home=os.path.expanduser('~')
    return {'os':platform.system().lower(),'arch':{'x86_64':'amd64','aarch64':'arm64'}.get(platform.machine(),platform.machine()),'hostname':socket.gethostname(),'fqdnHostname':socket.getfqdn(),'username':getpass.getuser(),'homeDir':home,'rawHomeDir':home,'sourceDir':os.path.abspath(os.path.expanduser(source)),'destDir':os.path.abspath(os.path.expanduser(dest)),'command':command,'commandDir':os.getcwd(),'pathSeparator':os.sep,'pathListSeparator':os.pathsep}

def main(argv):
    if not argv or argv[0] in ('--help','-h','--version','version'):
        base=dispatch(argv)
