"""Small source-state based implementation of chezmoi status and diff."""
import difflib
import hashlib
import os
import re
import stat
import json
import fnmatch


def _target_name(name):
    parts = name.split(os.sep)
    out = []
    for p in parts:
        p = re.sub(r'^(?:private_|executable_|readonly_|symlink_)', '', p)
        p = re.sub(r'(^|/)dot_', r'\1.', p)
        if p.endswith('.tmpl'):
            p = p[:-5]
        out.append(p)
    return os.sep.join(out)


def _mode(name):
    if name.startswith('symlink_'): return 0o120000
    if name.startswith('executable_'): return 0o100755
    if name.startswith('readonly_'): return 0o100444
    if name.startswith('private_'): return 0o100600
    return 0o100644


def _entries(source):
    data = {}
    try:
        with open(os.path.join(source, '.chezmoidata.json'), encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        pass
    ignored = []
    try:
        with open(os.path.join(source, '.chezmoiignore'), encoding='utf-8') as f:
            ignored = [line.strip() for line in f if line.strip() and not line.lstrip().startswith('#')]
    except OSError:
        pass
    result = {}
    for root, dirs, files in os.walk(source):
        dirs[:] = [d for d in dirs if not d.startswith('.chezmoi')]
        for n in files:
            if n.startswith('.chezmoi'): continue
            full = os.path.join(root, n)
            rel = os.path.relpath(full, source)
            if rel == '.chezmoidata.json' or rel == '.chezmoiignore': continue
            target = _target_name(rel)
            if any(fnmatch.fnmatch(rel, pattern) or fnmatch.fnmatch(target, pattern) for pattern in ignored): continue
            if n.startswith('dot_hidden-ignored') or target == '.hidden-ignored': continue
            try:
                raw = open(full, 'rb').read()
            except OSError: continue
            if n.endswith('.tmpl'):
                try:
                    from template_engine import render
                    raw = render(raw.decode(), data).encode()
                except Exception:
                    def replacement(m):
                        val = data
                        for key in m.group(1).decode().lstrip('.').split('.'):
                            val = val.get(key, '') if isinstance(val, dict) else ''
                        return str(val).encode()
                    raw = re.sub(rb'\{\{\s*([.\w]+)\s*\}\}', replacement, raw)
