    return result


def _blob(data):
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()


def _actual(path):
    try:
        st = os.lstat(path)
        if stat.S_ISLNK(st.st_mode): return os.readlink(path).encode(), 0o120000
        if stat.S_ISREG(st.st_mode): return open(path, 'rb').read(), 0o100000 | (st.st_mode & 0o777)
