        target, mode, kind = entries[name]
        if included is not None and kind not in included: continue
        if kind in excluded: continue
        path = os.path.join(destination, name)
        actual = _actual(path)
        if command == 'status':
            if actual is None: rows.append(' A ' + name)
            elif actual[0] != target: rows.append(' M ' + name)
            elif actual[1] != mode: rows.append(' M ' + name)
            continue
        old = actual[0] if actual else b''
        oldmode = actual[1] if actual else mode
        if actual is not None and old == target and oldmode == mode: continue
        oldhash = _blob(old) if actual else '0' * 40
        newhash = _blob(target)
        mode_s = lambda m: ('120000' if m == 0o120000 else format(m & 0o177777, '06o'))
        header = [f'diff --git a/{name} b/{name}', f'new file mode {mode_s(mode)}' if actual is None else (f'old mode {mode_s(oldmode)}\nnew mode {mode_s(mode)}' if oldmode != mode else ''), f'index {oldhash}..{newhash}' + ('' if actual is None else ' ' + mode_s(mode)), '--- ' + ('/dev/null' if actual is None else 'a/' + name), '+++ b/' + name]
